00074 // PSS data that is queued whilst base frames are decoded
00075 typedef struct {
00076     Packet packet;
00077     bool is_base_idr;
00078 } PssPacket;
00079 
00080 #define QUEUE_LIMIT 32
00081 
00082 static bool compare_packet_timestamps(const lctm::Packet &l, const lctm::Packet &r) {
00083     uint64_t lt = l.timestamp();
00084     uint64_t rt = r.timestamp();
00085     int64_t d = (rt - lt);
00086     return d < 0;
00087 }
00088 
00089 struct BufferCompare {
00090     bool operator()(const PssPacket &l, const PssPacket &r) { return compare_packet_timestamps(l.packet, r.packet); }
00091 };
