00156 void BaseVideoDecoderHM::push_au(const uint8_t *data, size_t data_size, uint64_t pts, bool is_base_idr, int iPictureType) {
00157     if (data) {
00158         // Temp. copy of AU
00159         vector<uint8_t> b(data, data + data_size);
00160 
00161         // Pick out enhancement data - may be removed - new size is returned
00162         size_t new_size =
00163             scan_enhancement(b.data(), data_size, encapsulation_, BaseCoding_AVC, pts, [is_base_idr, this](const Packet &pkt) {
00164                 this->enhancement_queue_.push({pkt, is_base_idr});
00165             });
00166 
00167         goReportStructure.miTimeStamp = (int)(pts);
00168         goReportStructure.miPictureType = iPictureType;
00169         goReportStructure.miBaseSize = (int)(new_size);
00170         goReportStructure.miEnhancementSize = (int)(data_size - new_size);
00171         goReportQueue.push(goReportStructure);
00172 
00173         b.resize(new_size);
00174 
00175         // Flush any previous buffer
00176         if (!buffer_.empty())
00177             push_es(buffer_.data(), buffer_.size(), pts, is_base_idr);
00178 
00179         buffer_.swap(b);
00180     } else {
00181         if (!buffer_.empty()) {
00182             push_es(buffer_.data(), buffer_.size(), pts, is_base_idr);
00183         }
00184 
00185         flush();
00186     }
00187 }
00188 
00189 void BaseVideoDecoderHM::push_es(const uint8_t *data, size_t data_size, uint64_t pts, bool is_base_idr) {
00190 
00191     // Fixup NALU start code - if first is 3 bytes, make it 4
00192     if (data[0] == '\0' && data[1] == '\0' && data[2] == '\1') {
00193         char const zero = '\0';
00194         base_bitstream_.put(0);
00195     }
00196 
00197     // Accumulate AUs into a temporary file
00198     base_bitstream_.write((const char *)data, data_size);
00199 }
00200 
00201 void BaseVideoDecoderHM::flush() {
00202     Bool openedRecon = false;
00203     bool loopFiltered = false;
00204     int poc = 0;
00205     TComList<TComPic *> *pcListPic = NULL;
00206     InputByteStream bytestream(base_bitstream_);
00207 
00208     while (!!base_bitstream_) {
00209         streampos location = base_bitstream_.tellg();
00210 
00211         AnnexBStats stats = AnnexBStats();
00212         InputNALUnit nalu;
00213         byteStreamNALUnit(bytestream, nalu.getBitstream().getFifo(), stats);
00214 
00215         // call actual decoding function
00216         Bool bNewPicture = false;
00217         if (nalu.getBitstream().getFifo().empty()) {
00218             WARN("Attempt to decode an empty NAL unit");
00219         } else {
00220             read(nalu);
00221             int skip = 0;
00222             bNewPicture = m_cTDecTop.decode(nalu, skip, m_iPOCLastDisplay);
00223 
00224             if (bNewPicture) {
00225                 base_bitstream_.clear();
00226                 base_bitstream_.seekg(location - streamoff(3));
00227                 bytestream.reset();
00228             }
00229         }
00230 
00231         if ((bNewPicture || !base_bitstream_ || nalu.m_nalUnitType == NAL_UNIT_EOS) && !m_cTDecTop.getFirstSliceInSequence()) {
00232             if (!loopFiltered || base_bitstream_) {
00233                 m_cTDecTop.executeLoopFilters(poc, pcListPic);
00234             }
00235             loopFiltered = (nalu.m_nalUnitType == NAL_UNIT_EOS);
00236             if (nalu.m_nalUnitType == NAL_UNIT_EOS) {
00237                 m_cTDecTop.setFirstSliceInSequence(true);
00238             }
00239         } else if ((bNewPicture || !base_bitstream_ || nalu.m_nalUnitType == NAL_UNIT_EOS) &&
00240                    m_cTDecTop.getFirstSliceInSequence()) {
00241             m_cTDecTop.setFirstSliceInPicture(true);
00242         }
00243 
00244         if (pcListPic) {
00245             if (!openedRecon) {
00246                 const BitDepths &bitDepths =
00247                     pcListPic->front()->getPicSym()->getSPS().getBitDepths(); // use bit depths of first reconstructed picture.
00248                 for (UInt channelType = 0; channelType < MAX_NUM_CHANNEL_TYPE; channelType++) {
00249                     if (m_outputBitDepth[channelType] == 0) {
00250                         m_outputBitDepth[channelType] = bitDepths.recon[channelType];
00251                     }
00252                 }
00253 
00254                 m_cTVideoIOYuvRecon.open(this, m_outputBitDepth, m_outputBitDepth, bitDepths.recon); // write mode
00255                 openedRecon = true;
00256             }
00257 
00258             // write reconstruction to file
00259             if (bNewPicture) {
00260                 WriteOutput(pcListPic, nalu.m_temporalId);
00261             }
00262             if ((bNewPicture || nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_CRA) && m_cTDecTop.getNoOutputPriorPicsFlag()) {
00263                 m_cTDecTop.checkNoOutputPriorPics(pcListPic);
00264                 m_cTDecTop.setNoOutputPriorPicsFlag(false);
00265             }
00266             if (bNewPicture &&
00267                 (nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_IDR_W_RADL || nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_IDR_N_LP ||
00268                  nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_BLA_N_LP || nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_BLA_W_RADL ||
00269                  nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_BLA_W_LP)) {
00270                 FlushOutput(pcListPic);
00271             }
00272             if (nalu.m_nalUnitType == NAL_UNIT_EOS) {
00273                 WriteOutput(pcListPic, nalu.m_temporalId);
00274                 m_cTDecTop.setFirstSliceInPicture(false);
00275             }
00276             // write reconstruction to file -- for additional bumping as defined in C.5.2.3
00277             if (!bNewPicture && nalu.m_nalUnitType >= NAL_UNIT_CODED_SLICE_TRAIL_N &&
00278                 nalu.m_nalUnitType <= NAL_UNIT_RESERVED_VCL31) {
00279                 WriteOutput(pcListPic, nalu.m_temporalId);
00280             }
00281         }
00282     }
00283 
00284     FlushOutput(pcListPic);
00285 
00286     // delete buffers
00287     m_cTDecTop.deletePicBuffer();
00288 }
00289 
00293 void BaseVideoDecoderHM::WriteOutput(TComList<TComPic *> *pcListPic, unsigned int tId) {
00294     if (pcListPic->empty()) {
00295         return;
00296     }
00297 
00298     TComList<TComPic *>::iterator iterPic = pcListPic->begin();
00299     Int numPicsNotYetDisplayed = 0;
00300     Int dpbFullness = 0;
00301     const TComSPS *activeSPS = &(pcListPic->front()->getPicSym()->getSPS());
00302     UInt numReorderPicsHighestTid;
00303     UInt maxDecPicBufferingHighestTid;
00304     UInt maxNrSublayers = activeSPS->getMaxTLayers();
00305 
00306     numReorderPicsHighestTid = activeSPS->getNumReorderPics(maxNrSublayers - 1);
00307     maxDecPicBufferingHighestTid = activeSPS->getMaxDecPicBuffering(maxNrSublayers - 1);
00308 
00309     while (iterPic != pcListPic->end()) {
00310         TComPic *pcPic = *(iterPic);
00311         if (pcPic->getOutputMark() && pcPic->getPOC() > m_iPOCLastDisplay) {
00312             numPicsNotYetDisplayed++;
00313             dpbFullness++;
00314         } else if (pcPic->getSlice(0)->isReferenced()) {
00315             dpbFullness++;
00316         }
00317         iterPic++;
00318     }
00319 
00320     iterPic = pcListPic->begin();
00321 
00322     if (numPicsNotYetDisplayed > 2) {
00323         iterPic++;
00324     }
00325 
00326     TComPic *pcPic = *(iterPic);
00327     if (numPicsNotYetDisplayed > 2 && pcPic->isField()) // Field Decoding
00328     {
00329         TComList<TComPic *>::iterator endPic = pcListPic->end();
00330         endPic--;
00331         iterPic = pcListPic->begin();
00332         while (iterPic != endPic) {
00333             TComPic *pcPicTop = *(iterPic);
00334             iterPic++;
00335             TComPic *pcPicBottom = *(iterPic);
00336 
00337             if (pcPicTop->getOutputMark() && pcPicBottom->getOutputMark() &&
00338                 (numPicsNotYetDisplayed > numReorderPicsHighestTid || dpbFullness > maxDecPicBufferingHighestTid) &&
00339                 (!(pcPicTop->getPOC() % 2) && pcPicBottom->getPOC() == pcPicTop->getPOC() + 1) &&
00340                 (pcPicTop->getPOC() == m_iPOCLastDisplay + 1 || m_iPOCLastDisplay < 0)) {
00341                 // write to file
00342                 numPicsNotYetDisplayed = numPicsNotYetDisplayed - 2;
00343                 const Window &conf = pcPicTop->getConformanceWindow();
00344                 const Window defDisp = pcPicTop->getDefDisplayWindow();
00345                 const Bool isTff = pcPicTop->isTopField();
00346 
00347                 m_cTVideoIOYuvRecon.write(pcPicTop->getPicYuvRec(), pcPicBottom->getPicYuvRec(),
00348                                           IPCOLOURSPACE_UNCHANGED /*m_outputColourSpaceConvert*/,
00349                                           conf.getWindowLeftOffset() + defDisp.getWindowLeftOffset(),
00350                                           conf.getWindowRightOffset() + defDisp.getWindowRightOffset(),
00351                                           conf.getWindowTopOffset() + defDisp.getWindowTopOffset(),
00352                                           conf.getWindowBottomOffset() + defDisp.getWindowBottomOffset(), NUM_CHROMA_FORMAT, isTff);
00353 
00354                 // update POC of display order
00355                 m_iPOCLastDisplay = pcPicBottom->getPOC();
00356 
00357                 // erase non-referenced picture in the reference picture list after display
00358                 if (!pcPicTop->getSlice(0)->isReferenced() && pcPicTop->getReconMark() == true) {
00359                     pcPicTop->setReconMark(false);
00360 
00361                     // mark it should be extended later
00362                     pcPicTop->getPicYuvRec()->setBorderExtension(false);
00363                 }
00364                 if (!pcPicBottom->getSlice(0)->isReferenced() && pcPicBottom->getReconMark() == true) {
00365                     pcPicBottom->setReconMark(false);
00366 
00367                     // mark it should be extended later
00368                     pcPicBottom->getPicYuvRec()->setBorderExtension(false);
00369                 }
00370                 pcPicTop->setOutputMark(false);
00371                 pcPicBottom->setOutputMark(false);
00372             }
00373         }
00374     } else if (!pcPic->isField()) // Frame Decoding
00375     {
00376         iterPic = pcListPic->begin();
00377 
00378         while (iterPic != pcListPic->end()) {
00379             pcPic = *(iterPic);
00380 
00381             if (pcPic->getOutputMark() && pcPic->getPOC() > m_iPOCLastDisplay &&
00382                 (numPicsNotYetDisplayed > numReorderPicsHighestTid || dpbFullness > maxDecPicBufferingHighestTid)) {
00383                 // write to file
00384                 numPicsNotYetDisplayed--;
00385                 if (pcPic->getSlice(0)->isReferenced() == false) {
00386                     dpbFullness--;
00387                 }
00388 
00389                 const Window &conf = pcPic->getConformanceWindow();
00390                 const Window defDisp = true /*m_respectDefDispWindow*/ ? pcPic->getDefDisplayWindow() : Window();
00391 
00392                 m_cTVideoIOYuvRecon.write(pcPic->getPicYuvRec(), IPCOLOURSPACE_UNCHANGED /*m_outputColourSpaceConvert*/,
00393                                           conf.getWindowLeftOffset() + defDisp.getWindowLeftOffset(),
00394                                           conf.getWindowRightOffset() + defDisp.getWindowRightOffset(),
00395                                           conf.getWindowTopOffset() + defDisp.getWindowTopOffset(),
00396                                           conf.getWindowBottomOffset() + defDisp.getWindowBottomOffset(), NUM_CHROMA_FORMAT,
00397                                           false /*m_bClipOutputVideoToRec709Range */);
00398 
00399                 // update POC of display order
00400                 m_iPOCLastDisplay = pcPic->getPOC();
00401 
00402                 // erase non-referenced picture in the reference picture list after display
00403                 if (!pcPic->getSlice(0)->isReferenced() && pcPic->getReconMark() == true) {
00404                     pcPic->setReconMark(false);
00405 
00406                     // mark it should be extended later
00407                     pcPic->getPicYuvRec()->setBorderExtension(false);
00408                 }
00409                 pcPic->setOutputMark(false);
00410             }
00411 
00412             iterPic++;
00413         }
00414     }
00415 }
00416 
00419 void BaseVideoDecoderHM::FlushOutput(TComList<TComPic *> *pcListPic) {
00420     if (!pcListPic || pcListPic->empty()) {
00421         return;
00422     }
00423     TComList<TComPic *>::iterator iterPic = pcListPic->begin();
00424 
00425     iterPic = pcListPic->begin();
00426     TComPic *pcPic = *(iterPic);
00427 
00428     if (pcPic->isField()) // Field Decoding
00429     {
00430         TComList<TComPic *>::iterator endPic = pcListPic->end();
00431         endPic--;
00432         TComPic *pcPicTop, *pcPicBottom = NULL;
00433         while (iterPic != endPic) {
00434             pcPicTop = *(iterPic);
00435             iterPic++;
00436             pcPicBottom = *(iterPic);
00437 
00438             if (pcPicTop->getOutputMark() && pcPicBottom->getOutputMark() && !(pcPicTop->getPOC() % 2) &&
00439                 (pcPicBottom->getPOC() == pcPicTop->getPOC() + 1)) {
00440                 // write to file
00441                 const Window &conf = pcPicTop->getConformanceWindow();
00442                 const Window defDisp = true /*m_respectDefDispWindow*/ ? pcPicTop->getDefDisplayWindow() : Window();
00443                 const Bool isTff = pcPicTop->isTopField();
00444                 m_cTVideoIOYuvRecon.write(pcPicTop->getPicYuvRec(), pcPicBottom->getPicYuvRec(),
00445                                           IPCOLOURSPACE_UNCHANGED /*m_outputColourSpaceConvert*/,
00446                                           conf.getWindowLeftOffset() + defDisp.getWindowLeftOffset(),
00447                                           conf.getWindowRightOffset() + defDisp.getWindowRightOffset(),
00448                                           conf.getWindowTopOffset() + defDisp.getWindowTopOffset(),
00449                                           conf.getWindowBottomOffset() + defDisp.getWindowBottomOffset(), NUM_CHROMA_FORMAT, isTff);
00450 
00451                 // update POC of display order
00452                 m_iPOCLastDisplay = pcPicBottom->getPOC();
00453 
00454                 // erase non-referenced picture in the reference picture list after display
00455                 if (!pcPicTop->getSlice(0)->isReferenced() && pcPicTop->getReconMark() == true) {
00456                     pcPicTop->setReconMark(false);
00457 
00458                     // mark it should be extended later
00459                     pcPicTop->getPicYuvRec()->setBorderExtension(false);
00460                 }
00461                 if (!pcPicBottom->getSlice(0)->isReferenced() && pcPicBottom->getReconMark() == true) {
00462                     pcPicBottom->setReconMark(false);
00463 
00464                     // mark it should be extended later
00465                     pcPicBottom->getPicYuvRec()->setBorderExtension(false);
00466                 }
00467                 pcPicTop->setOutputMark(false);
00468                 pcPicBottom->setOutputMark(false);
00469 
00470                 if (pcPicTop) {
00471                     pcPicTop->destroy();
00472                     delete pcPicTop;
00473                     pcPicTop = NULL;
00474                 }
00475             }
00476         }
00477         if (pcPicBottom) {
00478             pcPicBottom->destroy();
00479             delete pcPicBottom;
00480             pcPicBottom = NULL;
00481         }
00482     } else // Frame decoding
00483     {
00484         while (iterPic != pcListPic->end()) {
00485             pcPic = *(iterPic);
00486 
00487             if (pcPic->getOutputMark()) {
00488                 // write to file
00489                 const Window &conf = pcPic->getConformanceWindow();
00490                 const Window defDisp = true /*m_respectDefDispWindow*/ ? pcPic->getDefDisplayWindow() : Window();
00491 
00492                 m_cTVideoIOYuvRecon.write(pcPic->getPicYuvRec(), IPCOLOURSPACE_UNCHANGED /*m_outputColourSpaceConvert*/,
00493                                           conf.getWindowLeftOffset() + defDisp.getWindowLeftOffset(),
00494                                           conf.getWindowRightOffset() + defDisp.getWindowRightOffset(),
00495                                           conf.getWindowTopOffset() + defDisp.getWindowTopOffset(),
00496                                           conf.getWindowBottomOffset() + defDisp.getWindowBottomOffset(), NUM_CHROMA_FORMAT,
00497                                           false /*m_bClipOutputVideoToRec709Range*/);
00498 
00499                 // update POC of display order
00500                 m_iPOCLastDisplay = pcPic->getPOC();
00501 
00502                 // erase non-referenced picture in the reference picture list after display
00503                 if (!pcPic->getSlice(0)->isReferenced() && pcPic->getReconMark() == true) {
00504                     pcPic->setReconMark(false);
00505 
00506                     // mark it should be extended later
00507                     pcPic->getPicYuvRec()->setBorderExtension(false);
00508                 }
00509                 pcPic->setOutputMark(false);
00510             }
00511             if (pcPic != NULL) {
00512                 pcPic->destroy();
00513                 delete pcPic;
00514                 pcPic = NULL;
00515             }
00516             iterPic++;
00517         }
00518     }
00519     pcListPic->clear();
00520     m_iPOCLastDisplay = -MAX_INT;
00521 }
00522 
00523 void BaseVideoDecoderHM::picture_begin(bool is16bit, UInt width, UInt height, ChromaFormat format) {
00524     output_frame_++;
00525     size_t frame_size = (width * height + 2 * (width / 2 * height / 2)) * (is16bit ? 2 : 1);
00526 
00527     output_buffer_.clear();
00528     output_buffer_.reserve(frame_size);
00529 
00530     base_picture_.bpp = is16bit ? 2 : 1;
00531     base_picture_.width_y = width;
00532     base_picture_.height_y = height;
00533     base_picture_.stride_y = width * base_picture_.bpp;
00534 
00535     base_picture_.width_uv = (format != CHROMA_444) ? (width / 2) : width;
00536     base_picture_.height_uv = (format == CHROMA_420) ? (height / 2) : height;
00537     base_picture_.stride_uv = base_picture_.width_uv * base_picture_.bpp;
00538 }
00539 
00540 int BaseVideoDecoderHM::write(const uint8_t *data, size_t size) {
00541     output_buffer_.insert(output_buffer_.end(), data, data + size);
00542     return (int)size;
00543 }
00544 
00545 void BaseVideoDecoderHM::picture_end() {
00546     base_picture_.data_y = output_buffer_.data();
00547     base_picture_.data_u = base_picture_.data_y + base_picture_.stride_y * base_picture_.height_y;
00548     base_picture_.data_v = base_picture_.data_u + base_picture_.stride_uv * base_picture_.height_uv;
00549 
00550     // Get next PSS from queue
00551     //
00552     CHECK(!enhancement_queue_.empty());
00553     PssPacket pss = enhancement_queue_.top();
00554     enhancement_queue_.pop();
00555 
00556     // Send to enhancement decoder
00557     //
00558     PacketView enhancement_view(pss.packet);
00559     output_.push_base_enhancement(&base_picture_, enhancement_view.data(), enhancement_view.size(), pss.packet.timestamp(),
00560                                   pss.is_base_idr);
00561 }
